// Simulate execute_command with basic sanitization (for demonstration)
char* execute_command(const char* command) {
    // Simple sanitization: check for suspicious patterns
    if (strstr(command, "..") || strstr(command, ";") || strstr(command, "|") || strstr(command, "&")) {
        fprintf(stderr, "Command injection attempt detected: %s\n", command);
        return NULL;
    }

    FILE* pipe = popen(command, "r");
    if (!pipe) {
        return NULL;
    }

    char buffer[1024];
    char* output = NULL;
    size_t size = 0;

    while (fgets(buffer, sizeof(buffer), pipe) != NULL) {
        size += strlen(buffer);
        output = realloc(output, size + 1);
        if (!output) {
            free(output);
            return NULL;
        }
        strcat(output, buffer);
    }

    pclose(pipe);
    return output;
}

